import { z } from 'zod';

import type { ToolDefinition } from '../types.ts';
import { ToolError, type AssistantTool, type ToolContext, type ToolOutput } from './tool-kit.ts';
import { TOOL_MODULES } from './tools/index.ts';

/**
 * The assistant's tool registry. Each tool lives in its own file in `./tools/` (see
 * `defineTool` in `./tool-kit.ts`); `./tools/index.ts` is generated by `npm run gen:tools`.
 */

export {
  formatDayLabel,
  formatTime,
  pickSpread,
  ToolError,
  type ToolContext,
  type ToolOutput,
} from './tool-kit.ts';
export { proposeBooking } from './tools/propose-booking.ts';
export { cancelDraft, confirmDraft } from './tools/cancel-draft.ts';

export type AssistantToolName = (typeof TOOL_MODULES)[number]['name'];

const TOOLS: readonly AssistantTool[] = [...TOOL_MODULES].sort((a, b) => a.order - b.order);
const BY_NAME = new Map<string, AssistantTool>(TOOLS.map((t) => [t.name, t]));

/** JSON Schemas the model sees, in `order`. */
export const ASSISTANT_TOOLS: ToolDefinition[] = TOOLS.map((t) => ({
  name: t.name,
  description: t.description,
  parameters: t.parameters,
}));

/**
 * Validates and runs one model tool call. Failures come back as `{ error }` results so the model
 * can recover (e.g. ask for the service) instead of the whole turn failing.
 */
export async function runTool(
  ctx: ToolContext,
  name: string,
  rawArgs: Record<string, unknown>,
): Promise<ToolOutput & { ok: boolean }> {
  const tool = BY_NAME.get(name);
  if (!tool) {
    return { ok: false, result: { error: { code: 'unknown_tool', message: `No tool ${name}` } } };
  }
  const parsed = tool.schema.safeParse(rawArgs ?? {});
  if (!parsed.success) {
    return {
      ok: false,
      result: { error: { code: 'invalid_arguments', message: z.prettifyError(parsed.error) } },
    };
  }
  try {
    return { ok: true, ...(await tool.handler(ctx, parsed.data)) };
  } catch (e) {
    if (e instanceof ToolError) {
      return { ok: false, result: { error: { code: e.code, message: e.message } } };
    }
    throw e;
  }
}
